static String buildJarFileName(String base, String version, String classifier) {
    if (classifier == null || classifier.isBlank()) return base + "-" + version + ".jar";
    return base + "-" + version + "-" + classifier + ".jar";
}
System.out.println(buildJarFileName("app","1.0.0","all"));
System.out.println(buildJarFileName("app","1.0.0",null));

static boolean isCompatible(String required, String actual) {
    return Double.parseDouble(actual) >= Double.parseDouble(required);
}
System.out.println(isCompatible("8.0", "8.10"));
System.out.println(isCompatible("8.0", "7.6"));

static String evaluateOverallGate(boolean testsPass, int checkstyleViolations, double coveragePercent) {
    if (!testsPass) return "FAIL: testy nie przeszly";
    if (checkstyleViolations > 0) return "FAIL: " + checkstyleViolations + " naruszen checkstyle";
    if (coveragePercent < 80) return "FAIL: pokrycie " + coveragePercent + "% < 80%";
    return "PASS";
}
System.out.println(evaluateOverallGate(true, 0, 85));

