static String recommendFatJarStrategy(boolean springBoot, boolean relocation, boolean plainJava) {
    if (springBoot) return "bootJar (wlasny mechanizm Spring Boot)";
    if (relocation) return "Shadow Plugin (obsluguje relocate)";
    if (plainJava) return "Shadow Plugin lub zwykly jar, zaleznie od potrzeby fat JAR";
    return "zwykly jar";
}
System.out.println(recommendFatJarStrategy(true, false, false));

