static void printTree(String node, Map<String,List<String>> g, int depth) {
    System.out.println("  ".repeat(depth) + node);
    for (String c : g.getOrDefault(node, List.of())) printTree(c, g, depth+1);
}
printTree("check", g, 0);

static void detectDuplicateClasses(List<String> jars) {
    Map<String,List<String>> byLib = new HashMap<>();
    for (String j : jars) {
        String[] parts = j.split("-");
        byLib.computeIfAbsent(parts[0], k -> new ArrayList<>()).add(j);
    }
    byLib.forEach((lib, versions) -> { if (versions.size() > 1) System.out.println("KONFLIKT: " + lib + " -> " + versions); });
}
detectDuplicateClasses(List.of("gson-2.8.0.jar","gson-2.11.0.jar","slf4j-1.7.jar"));

